data.mutation:
mutation (
  $payload: [ProductionSetupOutputCreatePayloadInput!]!
  $payloadBom: [ProductionSetupBomCreatePayloadInput!]!
  $payloadDistUpdate: [WorkOrderProcessDistributionUpdatePayloadInput!]!
  $payloadWorkOrderUpdate: [WorkOrderUpdatePayloadInput!]!
  $payloadWU:[WorkunitUpdatePayloadInput!]!
) {
  createProductionSetupOutput(payload: $payload) {
    id
  }
  createProductionSetupBom(payload: $payloadBom) {
    id
  }
  updateWorkOrderProcessDistribution(payload: $payloadDistUpdate) {
    id
  }
  updateWorkOrder(payload: $payloadWorkOrderUpdate) {
    id
  }
  updateWorkunit(payload : $payloadWU){
    id
  }
}

data.transform:
(
	$outputId := $cuid();
	$woProcess := workOrderProcess.edges.node;
	$request := $state.context.REQUEST.DATA;
	$wipBom := $woProcess[sequence < $request.workOrderProcess.sequence]^(>sequence)[0] ;
	$wipProduct := $request.workOrderProcess.workOrder.product.id;
 	{
		"payload": [
			{
				"create": $state.context
					.REQUEST
					.DATA
					.{
						"id": $outputId,
						"unitPerCycle": unitPerCycle,
						"quantity": balanceQuantity,
						"setBatch": balanceQuantity,
						"standardPackQuantity": workOrderProcess
							.standardPackQuantity,
						"virtual": false,
						"workunitId": workunitId,
						"workOrderProcessId": workOrderProcess.id,
						"workOrderProcessDistributionId": id
					}
			}
		],
		"payloadBom": [
			$state.context
				.REQUEST
				.DATA
				.workOrderProcess
				.workOrderProcessBoms
				.edges
				.node
				.{
					"create": {
						"addToBatch": 0,
						"priority": priority,
						"maximumUsage": maximumUsage,
						"minimumUsage": minimumUsage,
						"standardUsage": standardUsage,
						"consumptionTypeId": consumptionTypeId,
						"allowOverConsumption": allowOverConsumption,
						"validate": validate,
						"extProduct": extProduct,
						"reference": reference,
						"componentProductStrategyId": componentProductStrategyId,
						"componentProductId": componentProductId,
						"productionSetupOutputId": $outputId
					}
				}
		] ~> $append(
			[
				$wipBom.{
					"create": {
						"addToBatch": 0,
						"priority": 0,
						"maximumUsage": 1,
						"minimumUsage": 1,
						"standardUsage": 1,
						"consumptionTypeId": "standard",
						"allowOverConsumption": false,
						/* "validate": true, */
						"wip": true,
						"componentProductStrategyId": componentProductStrategyId,
						"componentProductId": $wipProduct,
						"productionSetupOutputId": $outputId,
						"wipWorkOrderProcessId": id
					}
				}
			]
		),
		"payloadDistUpdate": [
			$state.context
				.REQUEST
				.DATA
				.{
					"update": { "distributionStatusId": "In Process" },
					"where": { "id": id }
				}
		],
		"payloadWorkOrderUpdate": [
			$state.context
				.REQUEST
				.DATA
				.{
					"update": { "workOrderStatusId": "In Process" },
					"where": { "id": workOrderProcess.workOrderId }
				}
		],
		"payloadWU": {
			"update":{
				"lastTransactionTypeId": "Production Setup Add"
			},
			"where": {
				"id": $state.context.REQUEST.DATA.workunitId
			}
		}
		
	} 
)

data.responseTransform:
{
  "SUCCESS": false,
  "MESSAGE": $coalesce([$state.lastError.message,"Unexpected Error Occurred, review Dispatch Functions Data Flow Logs for more detail"])
}

data.variablesTransform:
(
	$newDistId := $cuid();
	$createNewDistributions := $state.context.CREATE_NEW_DISTRIBUTIONS;
	{
		"payloadCreateDistribution": $createNewDistributions ? [
			$state
				.context
				.LOCAL
				.distribution[balanceQuantity > 0]
				.{
					"create": $merge([
						$omit(
							$,
							[
								"id",
								"balanceQuantity",
								"quantity",
								"producedQuantity",
								"actualFinishAt",
								"actualStartAt",
								"scheduledFinishAt",
								"scheduledStartAt",
								"distributionStatusId"
							]
						),
						{
							"id": $newDistId,
							"quantity": balanceQuantity,
							"distributionStatusId": "Released"
						}
					])
				}
		] : [],
		"payloadUpdateDistribution": [
			$state
				.context
				.LOCAL
				.distribution
				.{
					"update": { 
						"distributionStatusId": "Complete",
						"quantity": producedQuantity 
					},
					"where": { "id": id }
				}
		],
		"payloadDependency": $createNewDistributions ? [
			$state
				.context
				.LOCAL
				.dependency
				.{
					"create": childWorkOrderProcessDistributionId
						= $state.context.LOCAL.output.id
						? {
							"childWorkOrderProcessDistributionId": $newDistId,
							"parentWorkOrderProcessDistributionId": parentWorkOrderProcessDistributionId
						}
						: {
							"childWorkOrderProcessDistributionId": childWorkOrderProcessDistributionId,
							"parentWorkOrderProcessDistributionId": $newDistId
						}
				}
		] : [],
		"payloadDeleteOutput": [$state.context.LOCAL.output.{
					"where": { "id": id }
				}
			],
		"payloadWU": {
			"update":{
				"lastTransactionTypeId": "Production Setup Clear"
			},
			"where": {
				"id": $state.context.REQUEST.DATA.workunitId
			}
		}
	}
)

data.query:
query WorkOrderProcess($where: WorkOrderProcessWhereInput) {
  workOrderProcess(where: $where) {
    edges {
      node {
        id
        processId
        sequence
      }
    }
  }
}

